import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from faretools.analysis import assign_clinics


def oracle(a, b):
    from bisect import bisect_left
    pts = sorted(set(a))
    out = []
    for spot in b:
        if not pts:
            out.append(None)
            continue
        k = bisect_left(pts, spot)
        left = pts[k - 1] if k > 0 else None
        right = pts[k] if k < len(pts) else None
        if left is None:
            out.append(right)
        elif right is None:
            out.append(left)
        else:
            out.append(left if spot - left <= right - spot else right)
    return out


def small_args(rng):
    depots = [rng.randint(0, 30) for _ in range(rng.randint(0, 6))]
    spots = [rng.randint(-3, 33) for _ in range(rng.randint(0, 8))]
    return (depots, spots)


def big_args(rng, n):
    depots = [rng.randint(0, 20 * n) for _ in range(n)]
    spots = [rng.randint(-50, 20 * n + 50) for _ in range(n)]
    return (depots, spots)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2000)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(assign_clinics(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2001)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            assign_clinics(*args)
            self.assertEqual(args, before)

