import unittest

from linemeter import BudgetExceeded, LineMeter
from nightly.analysis import peak_delay_total


def oracle(a, b):
    out, lo = [], 0
    for i, (ts, _) in enumerate(a):
        while a[lo][0] <= ts - b:
            lo += 1
        out.append(sum(sorted((lat for _, lat in a[lo:i + 1]), reverse=True)[:3]))
    return out


def small_args(rng):
