    for _ in range(rng.randint(0, 14)):
        ts += rng.randint(0, 4)
        reqs.append((ts, rng.randint(1, 50)))
    return (reqs, rng.randint(1, 12))


def big_args(rng, n):
    ts, reqs = 0, []
    for _ in range(n):
        ts += rng.randint(0, 2)
        reqs.append((ts, rng.randint(1, 5000)))
    return (reqs, 120)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2001)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(peak_delay_total(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2002)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            peak_delay_total(*args)
