"""nightly: calculations used by the nightly batch jobs."""
import heapq


def peak_delay_total(jobs, width):
    """Sum of the three longest queue delays within the last window of arrivals."""
    heap = []
    start = 0
    out = []
    for i, (ts, latency) in enumerate(jobs):
        heapq.heappush(heap, (-latency, i))
        while jobs[start][0] <= ts - width:
            start += 1
        total, kept = 0, []
        while heap and len(kept) < 3:
            negative, j = heapq.heappop(heap)
            if j < start:
                continue
            kept.append((negative, j))
            total -= negative
        for item in kept:
            heapq.heappush(heap, item)
        out.append(total)
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

