def peak_delay_total(jobs, width):
    """Sum of the three longest queue delays within the last window of arrivals."""
    out = []
    for i, (ts, _) in enumerate(jobs):
        window = [latency for stamp, latency in jobs[:i + 1] if stamp > ts - width]
        out.append(sum(sorted(window, reverse=True)[:3]))
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

