import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from nightly.core import affected_services


def oracle(a, b):
    users = {}
    for module, deps in a.items():
        for dep in deps:
            users.setdefault(dep, set()).add(module)
    out = []
    for changed in b:
        seen = set(changed)
        frontier = list(seen)
        while frontier:
            nxt = []
            for m in frontier:
                for u in users.get(m, ()):
                    if u not in seen:
                        seen.add(u)
                        nxt.append(u)
            frontier = nxt
        out.append(sorted(seen))
    return out


def _imports(rng, n):
    names = ["m%03d" % i for i in range(n)]
    graph = {}
    for i, name in enumerate(names):
        lower = names[max(0, i - 4):i]
        graph[name] = rng.sample(lower, min(len(lower), rng.randint(1, 2))) if lower else []
    items = list(graph.items())
    rng.shuffle(items)
    return dict(items), names


def small_args(rng):
    graph, names = _imports(rng, rng.randint(1, 12))
    sets = [rng.sample(names, rng.randint(0, min(3, len(names)))) for _ in range(rng.randint(0, 5))]
    return (graph, sets)


def big_args(rng, n):
    graph, names = _imports(rng, n)
    sets = [rng.sample(names[: n // 3], 2) for _ in range(12)]
    return (graph, sets)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2002)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(affected_services(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2003)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            affected_services(*args)
            self.assertEqual(args, before)

