"""nightly: calculations used by the nightly batch jobs."""


def affected_services(calls, deploys):
    """Which services are affected by each deployment of an upstream service."""
    importers = {}
    for module, deps in calls.items():
        for dep in deps:
            importers.setdefault(dep, []).append(module)
    results = []
    for changed in deploys:
        dirty = set(changed)
        stack = list(dirty)
        while stack:
            current = stack.pop()
            for user in importers.get(current, ()):
                if user not in dirty:
                    dirty.add(user)
                    stack.append(user)
        results.append(sorted(dirty))
    return results


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

