from collections import deque


def alarm_chains(alerts, horizon):
    """How often a sensor warning turned into a critical alarm on the same machine."""
    recent = {}
    total = 0
    for host, kind, ts in alerts:
        live = recent.setdefault(host, deque())
        while live and ts - live[0] > horizon:
            live.popleft()
        if kind == "warn":
            live.append(ts)
        elif kind == "crit":
            total += len(live)
    return total


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

