"""buildgraph: calculations used by the nightly batch jobs."""


def alarm_chains(alerts, horizon):
    """How often a sensor warning turned into a critical alarm on the same machine."""
    total = 0
    for i, (host, kind, ts) in enumerate(alerts):
        if kind != "crit":
            continue
        for j in range(i):
            other_host, other_kind, other_ts = alerts[j]
            if other_host == host and other_kind == "warn" and ts - other_ts <= horizon:
                total += 1
