def bays_required(arrivals):
    """How many unloading bays a depot needs for its truck arrivals, turnaround included."""
    buffers = {"S": 1, "M": 2, "L": 4}
    events = []
    for arrive, depart, size in arrivals:
        events.append((arrive, 1))
        events.append((depart + buffers[size], -1))
    events.sort()
    busy = best = 0
    for _, delta in events:
        busy += delta
        best = max(best, busy)
    return best


