import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from opsmath.queries import plan_waves


def oracle(a):
    import sys
    sys.setrecursionlimit(10000)
    level = {}

    def depth(t):
        if t not in level:
            level[t] = 1 + max((depth(p) for p in a[t]), default=-1)
        return level[t]

    groups = {}
    for t in a:
        groups.setdefault(depth(t), []).append(t)
    return [sorted(groups[k]) for k in sorted(groups)]


def small_args(rng):
    size = rng.randint(0, 12)
    names = ["t%d" % i for i in range(size)]
    needs = {}
    for i, name in enumerate(names):
        pool = names[:i]
        needs[name] = rng.sample(pool, rng.randint(0, min(3, len(pool))))
    items = list(needs.items())
    rng.shuffle(items)
    return (dict(items),)


def big_args(rng, n):
    width = 4
    layers = [["t%d" % (layer * width + k) for k in range(width)] for layer in range(n // width)]
    needs = {}
    for idx, layer in enumerate(layers):
        for name in layer:
            if idx == 0:
                needs[name] = []
            else:
                needs[name] = rng.sample(layers[idx - 1], rng.randint(1, 3))
    items = list(needs.items())
    rng.shuffle(items)
    return (dict(items),)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2008)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(plan_waves(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2009)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            plan_waves(*args)
            self.assertEqual(args, before)

