from linemeter import BudgetExceeded, LineMeter
from opsmath.queries import plan_waves


def oracle(a):
    import sys
    sys.setrecursionlimit(10000)
    level = {}

    def depth(t):
        if t not in level:
            level[t] = 1 + max((depth(p) for p in a[t]), default=-1)
        return level[t]

    groups = {}
    for t in a:
        groups.setdefault(depth(t), []).append(t)
    return [sorted(groups[k]) for k in sorted(groups)]


def small_args(rng):
    size = rng.randint(0, 12)
    names = ["t%d" % i for i in range(size)]
    needs = {}
    for i, name in enumerate(names):
        pool = names[:i]
        needs[name] = rng.sample(pool, rng.randint(0, min(3, len(pool))))
    items = list(needs.items())
    rng.shuffle(items)
    return (dict(items),)


def big_args(rng, n):
    width = 4
    layers = [["t%d" % (layer * width + k) for k in range(width)] for layer in range(n // width)]
    needs = {}
    for idx, layer in enumerate(layers):
        for name in layer:
            if idx == 0:
                needs[name] = []
            else:
                needs[name] = rng.sample(layers[idx - 1], rng.randint(1, 3))
    items = list(needs.items())
    rng.shuffle(items)
    return (dict(items),)


PACKAGE_DIR = os.path.dirname(os.path.abspath(importlib.import_module("opsmath").__file__))
LIMIT = 96000


class PerformanceTests(unittest.TestCase):
    def test_executed_lines_stay_within_budget(self):
        rng = random.Random(2008)
        n = 1200
        args = big_args(rng, n)
        expected = oracle(*copy.deepcopy(args))
        meter = LineMeter(PACKAGE_DIR, budget=2 * LIMIT)
        try:
            with meter:
                got = plan_waves(*copy.deepcopy(args))
        except BudgetExceeded:
            self.fail("PERF: still running after %d executed lines of opsmath code (budget %d) on an input of size %d: the algorithm does far too much work" % (meter.lines, LIMIT, n))
        self.assertEqual(got, expected)
        self.assertLessEqual(meter.lines, LIMIT, "PERF: %d executed lines of opsmath code on an input of size %d (budget %d): the algorithm does too much work" % (meter.lines, n, LIMIT))

