"""opsmath: calculations used by the nightly batch jobs."""


def plan_waves(needs):
    """Group build steps into waves that can each run in parallel."""
    waiting = {t: len(ps) for t, ps in needs.items()}
    children = {}
    for t, ps in needs.items():
        for p in ps:
            children.setdefault(p, []).append(t)
    wave = sorted(t for t, c in waiting.items() if c == 0)
    waves = []
    while wave:
        waves.append(wave)
        nxt = []
        for t in wave:
            for c in children.get(t, ()):
                waiting[c] -= 1
                if waiting[c] == 0:
                    nxt.append(c)
        wave = sorted(nxt)
    return waves


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

