import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from buildgraph.compute import bandwidth_shares


def oracle(a, b):
    if sum(b) <= a:
        return list(b)
    order = sorted(b)
    remaining, level = a, 0
    for k, d in enumerate(order):
        share = remaining // (len(order) - k)
        if d <= share:
            remaining -= d
        else:
            level = share
            break
    out = [min(d, level) for d in b]
    left = a - sum(out)
    for i, d in enumerate(b):
        if left > 0 and d > level:
            out[i] += 1
            left -= 1
    return out


def small_args(rng):
    demands = [rng.randint(0, 12) for _ in range(rng.randint(0, 7))]
    return (rng.randint(0, 40), demands)


def big_args(rng, n):
    demands = [rng.randint(1, 4000) for _ in range(n)]
    return (sum(demands) // 2, demands)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2009)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(bandwidth_shares(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2010)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            bandwidth_shares(*args)
            self.assertEqual(args, before)

