"""buildgraph: calculations used by the nightly batch jobs."""


def bandwidth_shares(capacity, requests):
    """How a link's capacity is split among flows so that no one gets more than they ask for and the rest is shared evenly."""
    if sum(requests) <= capacity:
        return list(requests)
    lo, hi = 0, max(requests)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if sum(min(d, mid) for d in requests) <= capacity:
            lo = mid
        else:
            hi = mid - 1
    shares = [min(d, lo) for d in requests]
    left = capacity - sum(shares)
    for i, d in enumerate(requests):
        if left > 0 and d > lo:
            shares[i] += 1
            left -= 1
    return shares


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

