"""datajobs: calculations used by the nightly batch jobs."""


def release_eta(stages, release):
    """When the release is ready if every step starts as soon as its inputs exist."""
    known = {}

    def finish(task):
        if task not in known:
            hours, needs = stages[task]
            known[task] = hours + max((finish(dep) for dep in needs), default=0)
        return known[task]

    return finish(release)


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

