"""buildgraph: calculations used by the nightly batch jobs."""
import bisect


def balances_as_of(ledger, questions):
    """Account balances at the moments an auditor asks about."""
    times, sums = {}, {}
    for ts, owner, delta in ledger:
        times.setdefault(owner, []).append(ts)
        running = sums.setdefault(owner, [0])
        running.append(running[-1] + delta)
    out = []
    for account, moment in questions:
        k = bisect.bisect_right(times.get(account, []), moment)
        out.append(sums.get(account, [0])[k])
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

