from collections import deque


def followups_counted(log, within):
    """Number of warning-then-failure pairs in a service log."""
    recent = {}
    total = 0
    for host, kind, ts in log:
        live = recent.setdefault(host, deque())
        while live and ts - live[0] > within:
            live.popleft()
        if kind == "warn":
            live.append(ts)
        elif kind == "crit":
            total += len(live)
    return total


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

