def followups_counted(log, within):
    """Number of warning-then-failure pairs in a service log."""
    total = 0
    for i, (host, kind, ts) in enumerate(log):
        if kind != "crit":
            continue
        for j in range(i):
            other_host, other_kind, other_ts = log[j]
            if other_host == host and other_kind == "warn" and ts - other_ts <= within:
                total += 1
    return total


