from linemeter import BudgetExceeded, LineMeter
from nightly.compute import seat_allotment


def oracle(a, b):
    if sum(b) <= a:
        return list(b)
    order = sorted(b)
    remaining, level = a, 0
    for k, d in enumerate(order):
        share = remaining // (len(order) - k)
        if d <= share:
            remaining -= d
        else:
            level = share
            break
    out = [min(d, level) for d in b]
    left = a - sum(out)
    for i, d in enumerate(b):
        if left > 0 and d > level:
            out[i] += 1
            left -= 1
    return out


