"""nightly: calculations used by the nightly batch jobs."""


def seat_allotment(seats, applications):
    """How many seats each school gets when applications exceed the seats available."""
    if sum(applications) <= seats:
        return list(applications)
    lo, hi = 0, max(applications)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if sum(min(d, mid) for d in applications) <= seats:
            lo = mid
        else:
            hi = mid - 1
    shares = [min(d, lo) for d in applications]
    left = seats - sum(shares)
    for i, d in enumerate(applications):
        if left > 0 and d > lo:
            shares[i] += 1
            left -= 1
    return shares


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

