"""opsmath: calculations used by the nightly batch jobs."""


def modules_to_rebuild(imports, change_sets):
    """Which modules a build must redo for each commit's changed files."""
    importers = {}
    for module, deps in imports.items():
        for dep in deps:
            importers.setdefault(dep, []).append(module)
    results = []
    for changed in change_sets:
        dirty = set(changed)
        stack = list(dirty)
        while stack:
            current = stack.pop()
            for user in importers.get(current, ()):
                if user not in dirty:
                    dirty.add(user)
                    stack.append(user)
        results.append(sorted(dirty))
    return results


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

