"""faretools: calculations used by the nightly batch jobs."""
import heapq


def slowest_three_sum(requests, span):
    """A load-balancer health score: the three slowest responses within the trailing window, summed."""
    heap = []
    start = 0
    out = []
    for i, (ts, latency) in enumerate(requests):
        heapq.heappush(heap, (-latency, i))
        while requests[start][0] <= ts - span:
            start += 1
        total, kept = 0, []
        while heap and len(kept) < 3:
            negative, j = heapq.heappop(heap)
            if j < start:
                continue
            kept.append((negative, j))
            total -= negative
        for item in kept:
            heapq.heappush(heap, item)
        out.append(total)
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

